package com.ichi2.anki.dialogs

import android.view.KeyEvent
import com.ichi2.anki.reviewer.Binding

typealias KeyCode = Int

object KeySelectionDialogUtils {
    /** Bind the physical key code, not the character generated by the keyboard layout. */
    fun keyBinding(
        event: KeyEvent,
        isValidKeyCode: (KeyCode) -> Boolean,
    ): Binding.KeyCode? =
        if (event.action == KeyEvent.ACTION_DOWN) {
            Binding
                .possibleKeyBindings(event)
                .filterIsInstance<Binding.KeyCode>()
                .firstOrNull { isValidKeyCode(it.keycode) }
        } else {
            null
        }

    fun disallowModifierKeyCodes(): (KeyCode) -> Boolean {
        val modifierKeyCodes =
            hashSetOf(
                KeyEvent.KEYCODE_SHIFT_LEFT,
                KeyEvent.KEYCODE_SHIFT_RIGHT,
                KeyEvent.KEYCODE_CTRL_LEFT,
                KeyEvent.KEYCODE_CTRL_RIGHT,
                KeyEvent.KEYCODE_ALT_LEFT,
                KeyEvent.KEYCODE_ALT_RIGHT,
                KeyEvent.KEYCODE_META_LEFT,
                KeyEvent.KEYCODE_META_RIGHT,
                KeyEvent.KEYCODE_FUNCTION,
            )
        return { !modifierKeyCodes.contains(it) }
    }
}
